WITH metrics AS (SELECT *, NTILE(4) OVER (PARTITION BY level ORDER BY salary ASC, id ASC) AS salary_bucket, NTILE(3) OVER (PARTITION BY level, manager_id ORDER BY salary DESC, id ASC) AS salary_bucket_2 FROM employees) SELECT CASE WHEN salary >= 163000 THEN 'LARGE' ELSE 'SMALL' END AS salary_tier, CASE WHEN salary_bucket_2 >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS salary_bucket_2_tier, COUNT(DISTINCT id) AS distinct_ids, SUM(CASE WHEN level = 'L3' THEN salary_bucket_2 ELSE 0 END) AS l3_salary_bucket_2, ROUND(AVG(salary), 2) AS avg_salary, COUNT(*) AS row_count, MIN(salary_bucket) AS min_salary_bucket, SIZE(COLLECT_SET(job_title)) AS num_job_titles, GROUPING_ID() AS gid FROM metrics GROUP BY CUBE (CASE WHEN salary >= 163000 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN salary_bucket_2 >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY row_count DESC
